cd /app && psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
SELECT 'proposals' AS tbl, id, author_id, community_id, selected, published_at, retired_at FROM proposals LIMIT 20;
SELECT 'proposal_notifications', id, proposal_id, title FROM proposal_notifications;
SELECT 'dashboard_actions', id, title, action_type, active, published_proposal FROM dashboard_actions;
SELECT 'dashboard_executed_actions', id, proposal_id, action_id FROM dashboard_executed_actions;
SELECT 'dashboard_administrator_tasks', id, source_type, source_id, user_id FROM dashboard_administrator_tasks;
SELECT 'communities', id FROM communities;
SELECT 'topics', id, community_id, title FROM topics;
SELECT 'follows', id, user_id, followable_type, followable_id FROM follows;
SELECT 'votes', votable_type, count(*) FROM votes GROUP BY votable_type;
SELECT 'comments', commentable_type, count(*) FROM comments GROUP BY commentable_type;
SELECT 'notifications', notifiable_type, count(*) FROM notifications GROUP BY notifiable_type;
SELECT 'flags', flaggable_type, count(*) FROM flags GROUP BY flaggable_type;
SELECT 'activities', actionable_type, count(*) FROM activities GROUP BY actionable_type;
SELECT 'map_locations', id, proposal_id, investment_id, mappable_type, mappable_id FROM map_locations;
SELECT 'related_contents', id, parent_relationable_type, parent_relationable_id, child_relationable_type, child_relationable_id FROM related_contents;
SELECT 'taggings', taggable_type, count(*) FROM taggings GROUP BY taggable_type;
SELECT 'poll_questions', id, poll_id, proposal_id FROM poll_questions;
SELECT 'web_sections', id, name FROM web_sections;
SELECT 'site_customization_pages', id, slug FROM site_customization_pages;
SELECT 'sdg_phases', id, kind FROM sdg_phases;
SELECT 'settings (proposal/dashboard/etc)', id, key, value FROM settings WHERE key ILIKE '%proposal%' OR key ILIKE '%dashboard%' OR key ILIKE '%communit%' OR key ILIKE '%feature%' OR key ILIKE '%process%';
